// Confirms the incoming item is a well-formed Planner Contract addressed
// to this agent (docs/contracts/planner-contract.md) before any
// request-building logic runs. This is the only node that validates the
// contract's envelope shape - later nodes trust it and only validate
// their own narrow concern (no duplicated validation logic).
const STAGE = 'api_request_builder';
const WORKFLOW_VERSION = '1.0';

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

// ERROR payloads produced upstream (ingestion) are not test cases and
// must not be re-validated as a contract - pass them through unchanged,
// same convention as 01-ingestion.
if (item && item.status === 'ERROR') {
  return { json: item };
}

if (typeof item !== 'object' || item === null || Array.isArray(item)) {
  return { json: errorPayload(
    'INVALID_PLANNER_CONTRACT',
    'Planner Contract must be a JSON object',
    { received_type: Array.isArray(item) ? 'array' : typeof item }
  ) };
}

const requiredFields = ['workflow_version', 'agent', 'verification_type', 'next_node', 'test_case'];
const missingFields = requiredFields.filter((field) => item[field] === undefined || item[field] === null);

if (missingFields.length > 0) {
  return { json: errorPayload(
    'INVALID_PLANNER_CONTRACT',
    `Planner Contract is missing required field(s): ${missingFields.join(', ')}`,
    { missing_fields: missingFields }
  ) };
}

if (item.agent !== 'api') {
  return { json: errorPayload(
    'INVALID_PLANNER_CONTRACT',
    `API Request Builder only handles agent "api", received "${item.agent}"`,
    { agent: item.agent }
  ) };
}

if (typeof item.test_case !== 'object' || item.test_case === null || Array.isArray(item.test_case)) {
  return { json: errorPayload(
    'INVALID_PLANNER_CONTRACT',
    'Planner Contract test_case must be a JSON object',
    { received_type: Array.isArray(item.test_case) ? 'array' : typeof item.test_case }
  ) };
}

if (!item.test_case.test_id) {
  return { json: errorPayload(
    'INVALID_PLANNER_CONTRACT',
    'Planner Contract test_case is missing test_id',
    {}
  ) };
}

return { json: item };

// Resolves and validates the HTTP method + endpoint for this test case,
// and confirms the target base URL is configured. An explicit
// test_case.method / test_case.endpoint (or .path) wins if present;
// otherwise both are parsed from the leading "<METHOD> /<path>" pattern
// in test_case.steps - the same convention used in the worked example in
// docs/architecture/milestone-1.md section 6. This is a fixed,
// deterministic pattern match, not an AI guess.
const STAGE = 'api_request_builder';
const WORKFLOW_VERSION = '1.0';
const SUPPORTED_METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'];
const STEP_PATTERN = /^(\S+)\s+(\/\S*)/;

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

if (item.status === 'ERROR') {
  return { json: item };
}

const testCase = item.test_case;

let method = testCase.method ? String(testCase.method).trim().toUpperCase() : null;
let path = (testCase.endpoint || testCase.path) ? String(testCase.endpoint || testCase.path).trim() : null;

if (!method || !path) {
  const match = typeof testCase.steps === 'string' ? testCase.steps.trim().match(STEP_PATTERN) : null;
  if (!method && match) method = match[1].toUpperCase();
  if (!path && match) path = match[2];
}

if (!path) {
  return { json: errorPayload(
    'INVALID_ENDPOINT',
    `Could not determine an endpoint for test case "${testCase.test_id}" from an explicit endpoint/path field or from steps ("${testCase.steps}")`,
    { test_id: testCase.test_id, steps: testCase.steps }
  ) };
}

if (!method) {
  return { json: errorPayload(
    'MISSING_REQUIRED_FIELD',
    `Could not determine an HTTP method for test case "${testCase.test_id}" from an explicit method field or from steps ("${testCase.steps}")`,
    { test_id: testCase.test_id, missing_fields: ['method'] }
  ) };
}

if (!SUPPORTED_METHODS.includes(method)) {
  return { json: errorPayload(
    'UNSUPPORTED_HTTP_METHOD',
    `HTTP method "${method}" is not supported. Supported methods: ${SUPPORTED_METHODS.join(', ')}`,
    { test_id: testCase.test_id, method }
  ) };
}

const baseUrl = $env.SWAGGER_BASE_URL;

if (!baseUrl) {
  return { json: errorPayload(
    'MISSING_REQUIRED_FIELD',
    'SWAGGER_BASE_URL environment variable is not set - cannot build a request URL',
    { test_id: testCase.test_id, missing_fields: ['base_url'] }
  ) };
}

return { json: { ...item, __method: method, __path: path, __base_url: baseUrl } };

// Assembles the URL, headers, query parameters and body from the
// method/path/base_url validated by the previous node, plus whatever
// optional structured fields (query, request_body) the test case
// happens to carry. Milestone 1's Excel schema doesn't produce these
// fields today, so in practice body/query default to empty - they exist
// here for forward compatibility once a richer test-script format adds
// them, without requiring changes to this node's shape.
const STAGE = 'api_request_builder';
const WORKFLOW_VERSION = '1.0';
const BODY_METHODS = ['POST', 'PUT', 'PATCH'];

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

const item = $input.item.json;

if (item.status === 'ERROR') {
  return { json: item };
}

const testCase = item.test_case;
const method = item.__method;
const path = item.__path;
const baseUrl = item.__base_url;

const url = `${baseUrl.replace(/\/$/, '')}${path}`;
const headers = { 'Content-Type': 'application/json' };

let query = {};
if (testCase.query !== undefined && testCase.query !== null) {
  if (!isPlainObject(testCase.query)) {
    return { json: errorPayload(
      'INVALID_REQUEST_BODY',
      `test_case.query for "${testCase.test_id}" must be a plain object`,
      { test_id: testCase.test_id, query: testCase.query }
    ) };
  }
  query = testCase.query;
}

let body = null;
if (BODY_METHODS.includes(method)) {
  body = {};
  if (testCase.request_body !== undefined && testCase.request_body !== null) {
    if (!isPlainObject(testCase.request_body)) {
      return { json: errorPayload(
        'INVALID_REQUEST_BODY',
        `test_case.request_body for "${testCase.test_id}" must be a plain object`,
        { test_id: testCase.test_id, request_body: testCase.request_body }
      ) };
    }
    body = testCase.request_body;
  }
}

// Best-effort, non-blocking: a leading 3-digit status code in
// expected_result (e.g. "422 Unprocessable Entity") is captured for the
// future Decision Agent. If it can't be parsed, expected.status stays
// null rather than failing the whole request build.
const expectedStatusMatch = typeof testCase.expected_result === 'string'
  ? testCase.expected_result.match(/^(\d{3})/)
  : null;

const expected = {
  status: expectedStatusMatch ? Number(expectedStatusMatch[1]) : null,
  response: {}
};

return { json: { ...item, __url: url, __headers: headers, __query: query, __body: body, __expected: expected } };

// Resolves which authentication STRATEGY applies to this request - it
// never reads or embeds a real secret value. Doing so would put a
// plaintext credential into workflow execution data (visible in the n8n
// UI, potentially logged/stored) purely to describe intent. Per ADR 002,
// real credentials belong in n8n's own encrypted credential store; the
// workflow that actually executes the HTTP call (Task 3.2, not built
// here) is responsible for attaching one.
const STAGE = 'api_request_builder';
const WORKFLOW_VERSION = '1.0';
const SUPPORTED_AUTH_TYPES = ['none', 'bearer', 'api_key'];

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

if (item.status === 'ERROR') {
  return { json: item };
}

const testCase = item.test_case;
const authType = testCase.auth_type ? String(testCase.auth_type).trim().toLowerCase() : 'none';

if (!SUPPORTED_AUTH_TYPES.includes(authType)) {
  return { json: errorPayload(
    'UNSUPPORTED_AUTHENTICATION',
    `Authentication type "${authType}" is not supported. Supported types: ${SUPPORTED_AUTH_TYPES.join(', ')}`,
    { test_id: testCase.test_id, auth_type: authType }
  ) };
}

const credentials = authType === 'none' ? null : { strategy: authType, resolved_by: 'http_executor' };

return { json: { ...item, __auth_type: authType, __credentials: credentials } };

// Final assembly step: generates request_id/timeout/metadata and wraps
// everything the previous nodes computed into the API Request Contract
// (docs/contracts/api-request-contract.md). This is the only node that
// builds the final output shape - earlier nodes only ever add __-prefixed
// working fields, never the public contract fields themselves.
const CONTRACT_VERSION = '1.0';
const BUILDER_WORKFLOW_VERSION = '1.0';
const DEFAULT_TIMEOUT_MS = 30000;

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const item = $input.item.json;

if (item.status === 'ERROR') {
  return { json: item };
}

const parsedTimeout = Number($env.API_REQUEST_TIMEOUT_MS);
const timeout = Number.isFinite(parsedTimeout) && parsedTimeout > 0 ? parsedTimeout : DEFAULT_TIMEOUT_MS;

const apiRequestContract = {
  workflow_version: BUILDER_WORKFLOW_VERSION,
  contract_version: CONTRACT_VERSION,
  request_id: uuidv4(),
  method: item.__method,
  base_url: item.__base_url,
  path: item.__path,
  url: item.__url,
  headers: item.__headers,
  query: item.__query,
  body: item.__body,
  authentication: {
    type: item.__auth_type,
    credentials: item.__credentials
  },
  timeout,
  expected: item.__expected,
  test_case: item.test_case,
  metadata: {
    created_at: new Date().toISOString(),
    source_workflow: '01-ingestion',
    next_workflow: '03-http-executor'
  }
};

return { json: apiRequestContract };
